\documentclass{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    axis lines = middle,
    xlabel = $x$,
    ylabel = {$f(x)$},
    xmin = -2.2, xmax = 1.5,
    ymin = -0.2, ymax = 1.5,
    grid = both,
    minor tick num = 1,
    legend pos = north east,
    legend style = {draw=none, fill=none},
    width = 10cm,
    height = 8cm,
    samples = 100,
]
\addplot[domain=-2:0, thick, blue] {2^x};
\addlegendentry{$f(x)=2^x,\;x<0$}
% 取 f(0)=0.9，且 f(x)=0.9 - x^2，保证 0<x<1 时 f(x)<0.9
\addplot[domain=0:1, thick, red] {0.9 - x^2};
\addlegendentry{$f(x)=0.9-x^2,\;0\le x\le1$}
\addplot[only marks, mark=*, mark size=2pt, black] coordinates {(0,0.9)};
\end{axis}
\end{tikzpicture}
\end{document}
